from django.db import migrations, models


def hashear_contrasenas(apps, schema_editor):
    """Convierte a BCrypt las contraseñas que estaban guardadas en texto plano."""
    Usuario = apps.get_model('adminapp', 'Usuario')
    for usuario in Usuario.objects.all():
        if not usuario.contrasena.startswith(('$2a$', '$2b$', '$2y$')):
            usuario.contrasena = bcrypt.hashpw(usuario.contrasena.encode(), bcrypt.gensalt(rounds=10)).decode()
            usuario.save(update_fields=['contrasena'])


